class Solution {
public:
    long long largestPerimeter(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        long long sum = 0;
        long long best = -1;
        for (int i = 0; i < (int)nums.size(); i++) {
            if (i >= 2 && (long long)nums[i] < sum) {
                best = sum + nums[i];
            }
            sum += nums[i];
        }
        return best;
    }
};
